// ===================== SETTINGS (safe to change) =====================
const PROMPT_VERSION = 'v1';          // which prompt file to use: section.v1.md
const MODEL = 'gpt-4.1-mini';         // OpenAI model used to write sections
const REPO_RAW = 'https://raw.githubusercontent.com/mysteriouslyscentedtyrant/lead-magnet-generator/main';
// =====================================================================

// The page sends { document, sectionId }. "document" is the approved outline
// (written blocks and branding, if present, are ignored). The user may have
// edited the outline, so everything is checked again here.

const FORMATS = ['ebook', 'guide', 'checklist'];
const TONES = ['friendly', 'professional', 'bold', 'inspiring', 'conversational'];
const LENGTHS = ['short', 'standard', 'detailed'];
const RULES = {
  ebook:     { first: ['intro'],   middle: 'chapter', last: ['conclusion'],            min: 4, max: 7 },
  guide:     { first: ['problem'], middle: 'step',    last: ['mistakes', 'next_step'], min: 3, max: 9 },
  checklist: { first: [],          middle: 'group',   last: [],                        min: 3, max: 5 },
};

const body = $input.first().json.body || {};
const doc = body.document && typeof body.document === 'object' ? body.document : {};
const meta = doc.meta && typeof doc.meta === 'object' ? doc.meta : {};
const errors = [];

// Same cleaning as the outline workflow: no control/invisible characters,
// no angle brackets (can't break the prompt tags), no {{ }} (no placeholder injection).
function clean(value) {
  if (typeof value !== 'string') return '';
  return value
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(/[<>]/g, ' ')
    .replace(/\{\{|\}\}/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function text(value, label, min, max) {
  const v = clean(value);
  if (v.length < min) errors.push(`${label} must be at least ${min} characters.`);
  else if (v.length > max) errors.push(`${label} must be ${max} characters or less.`);
  return v;
}
function choice(value, label, allowed, fallback) {
  if ((value === undefined || value === null || value === '') && fallback !== undefined) return fallback;
  const v = String(value == null ? '' : value).trim().toLowerCase();
  if (!allowed.includes(v)) { errors.push(`${label} must be one of: ${allowed.join(', ')}.`); return ''; }
  return v;
}

const format = choice(doc.format, 'Format', FORMATS);
const topic = text(meta.topic, 'Topic', 3, 200);
const audience = text(meta.audience, 'Audience', 3, 400);
const offer = text(meta.offer || '', 'Offer', 0, 300);
const tone = choice(meta.tone, 'Tone', TONES, 'friendly');
const length = choice(meta.length, 'Length', LENGTHS, 'standard');
let language = clean(meta.language || '') || 'English';
if (!/^[\p{L} ()-]{2,30}$/u.test(language)) errors.push('Language must be a language name such as English or French.');

const title = text(doc.title, 'Title', 3, 90);
const subtitle = text(doc.subtitle || '', 'Subtitle', 0, 160);

const rawSections = Array.isArray(doc.sections) ? doc.sections : [];
if (rawSections.length < 1 || rawSections.length > 12) errors.push('The outline must have between 1 and 12 sections.');

const sections = rawSections.slice(0, 12).map((s, i) => {
  s = s && typeof s === 'object' ? s : {};
  const n = i + 1;
  const id = typeof s.id === 'string' && /^s[0-9]{1,2}$/.test(s.id) ? s.id : '';
  if (!id) errors.push(`Section ${n} has an invalid id.`);
  const keyPoints = Array.isArray(s.keyPoints) ? s.keyPoints : [];
  if (keyPoints.length > 8) errors.push(`Section ${n} has more than 8 key points.`);
  return {
    id,
    type: String(s.type || ''),
    heading: text(s.heading, `Section ${n} heading`, 2, 90),
    goal: text(s.goal || '', `Section ${n} goal`, 0, 200),
    keyPoints: keyPoints.slice(0, 8).map((k, j) => text(k, `Section ${n} key point ${j + 1}`, 1, 160)),
  };
});

const ids = sections.map(s => s.id);
if (new Set(ids).size !== ids.length) errors.push('Section ids must be unique.');

if (format) {
  const rule = RULES[format];
  const types = sections.map(s => s.type);
  const middle = types.length - rule.first.length - rule.last.length;
  const expected = [...rule.first, ...Array(Math.max(middle, 0)).fill(rule.middle), ...rule.last];
  if (middle < rule.min || middle > rule.max || types.join() !== expected.join()) {
    errors.push(`A ${format} needs ${rule.first.concat([`${rule.min}-${rule.max} x ${rule.middle}`], rule.last).join(', ')} sections in that order.`);
  }
}

const sectionId = typeof body.sectionId === 'string' ? body.sectionId : '';
const index = sections.findIndex(s => s.id === sectionId);
if (index === -1) errors.push('sectionId does not match any section in the outline.');

if (errors.length) {
  return [{ json: { ok: false, response: { ok: false, code: 'invalid_input', message: errors.slice(0, 5).join(' ') } } }];
}

const target = sections[index];
const outline = sections
  .map((s, i) => `${i + 1}. [${s.type}] ${s.heading}${i === index ? '   [THIS SECTION]' : ''}`)
  .join('\n');

return [{
  json: {
    ok: true,
    format,
    sectionId,
    sectionType: target.type,
    length,
    model: MODEL,
    promptVersion: PROMPT_VERSION,
    promptUrl: `${REPO_RAW}/prompts/section.${PROMPT_VERSION}.md`,
    schemaUrl: `${REPO_RAW}/schema/section.response.schema.json`,
    vars: {
      format, title, subtitle, audience,
      offer: offer || 'Not provided',
      tone, length, language,
      outline,
      position: `${index + 1} of ${sections.length}`,
      section_type: target.type,
      section_heading: target.heading,
      section_goal: target.goal || '(no goal given)',
      section_key_points: target.keyPoints.length ? target.keyPoints.map(k => '- ' + k).join('\n') : '- (no key points given: cover the heading)',
    },
  },
}];

// Builds the OpenAI request from the section prompt and response schema loaded from GitHub.
const settings = $('Validate input').first().json;
const promptText = String($('Load prompt').first().json.data || '').replace(/\r\n/g, '\n');
const schemaText = $('Load schema').first().json.data;

// Split the prompt file into its SYSTEM and USER parts.
const sysMarker = '===SYSTEM===';
const userMarker = '===USER===';
const sysAt = promptText.indexOf(sysMarker);
const userAt = promptText.indexOf(userMarker);
if (sysAt === -1 || userAt === -1 || userAt < sysAt) {
  throw new Error('Prompt file is missing the ===SYSTEM=== or ===USER=== marker: ' + settings.promptUrl);
}
const system = promptText.slice(sysAt + sysMarker.length, userAt).trim();
const userTemplate = promptText.slice(userAt + userMarker.length).trim();

// Fill {{placeholders}} in ONE pass, so text typed by a user is never re-read as a placeholder.
const vars = settings.vars;
const user = userTemplate.replace(/\{\{(\w+)\}\}/g, (match, key) => {
  if (!(key in vars)) throw new Error('Prompt uses an unknown placeholder: ' + match);
  return vars[key];
});

let responseSchema;
try {
  responseSchema = typeof schemaText === 'string' ? JSON.parse(schemaText) : schemaText;
} catch (e) {
  throw new Error('Response schema is not valid JSON: ' + settings.schemaUrl);
}

return [{
  json: {
    requestBody: {
      model: settings.model,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_schema', json_schema: responseSchema },
      max_completion_tokens: 3500,
    },
  },
}];

// Checks the AI answer for ONE section and cleans every block.
// Any problem throws an error -> the workflow answers with a generic "please try again".
const settings = $('Validate input').first().json;
const res = $input.first().json;

const choice = res.choices && res.choices[0];
const message = choice && choice.message;
if (!message) throw new Error('OpenAI returned no message: ' + JSON.stringify(res).slice(0, 500));
if (choice.finish_reason === 'length') throw new Error('Section was cut off (max_completion_tokens too low).');

if (message.refusal) {
  return [{ json: { response: { ok: false, code: 'rejected', sectionId: settings.sectionId,
    message: "We can't write this section. Please edit its heading or key points and try again." } } }];
}

let data;
try { data = JSON.parse(message.content); }
catch (e) { throw new Error('AI answer is not valid JSON: ' + String(message.content).slice(0, 500)); }

// ---------- text helpers ----------
const URL_RE = /\b(?:https?:\/\/|www\.)\S+/gi;
const EMAIL_RE = /\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g;
function tidy(value) {
  return String(value == null ? '' : value)
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(URL_RE, '')
    .replace(EMAIL_RE, '')
    .replace(/\*\*|__|`/g, '')
    .replace(/^\s*#{1,6}\s+/, '')
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .trim();
}
function cut(value, max) {
  const v = tidy(value);
  if (v.length <= max) return v;
  const short = v.slice(0, max);
  const space = short.lastIndexOf(' ');
  return (space > max * 0.6 ? short.slice(0, space) : short).replace(/[\s,;:-]+$/, '');
}
// List items: also drop leading bullets, numbers and checkboxes the design adds itself.
function item(value) {
  return cut(String(value == null ? '' : value).replace(/^\s*(\d+[.)](?=\s)|[-*\u2022\u2013](?=\s)|\[[ xX]?\]|\u2610|\u2611)\s*/, ''), 300);
}

const TEXT_TYPES = ['paragraph', 'subheading', 'tip', 'warning', 'example'];
const LIST_TYPES = ['bullets', 'steps', 'checklist'];

let blocks = (Array.isArray(data.blocks) ? data.blocks : []).map(b => {
  b = b && typeof b === 'object' ? b : {};
  const type = String(b.type || '');
  const items = (Array.isArray(b.items) ? b.items : []).map(item).filter(Boolean).slice(0, 15);
  if (TEXT_TYPES.includes(type)) {
    const t = cut(b.text, type === 'subheading' ? 90 : 1500);
    return t ? { type, text: t, items: [] } : null;
  }
  if (LIST_TYPES.includes(type)) {
    return items.length ? { type, text: cut(b.text, 300), items } : null;
  }
  if (type === 'template') {
    return items.length ? { type, text: cut(b.text, 120) || 'Template', items } : null;
  }
  return null;
}).filter(Boolean).slice(0, 30);

// A checklist group is exactly ONE checklist block of short items.
if (settings.sectionType === 'group') {
  const all = blocks.filter(b => b.type === 'checklist').flatMap(b => b.items);
  const seen = new Set();
  const unique = all
    .map(i => cut(i, 120))
    .filter(i => { const k = i.toLowerCase(); if (!i || seen.has(k)) return false; seen.add(k); return true; })
    .slice(0, 6);
  if (unique.length < 3) throw new Error('Checklist group has fewer than 3 items.');
  blocks = [{ type: 'checklist', text: '', items: unique }];
}

// Never start a section with a subheading only, never end on one.
while (blocks.length && blocks[blocks.length - 1].type === 'subheading') blocks.pop();
if (!blocks.length) throw new Error('Section has no usable content blocks.');

const words = blocks.reduce((n, b) => n + [b.text, ...b.items].join(' ').split(/\s+/).filter(Boolean).length, 0);

return [{
  json: {
    response: {
      ok: true,
      sectionId: settings.sectionId,
      blocks,
      generator: {
        promptVersion: settings.promptVersion,
        model: res.model || settings.model,
        tokens: res.usage ? res.usage.total_tokens : null,
        words,
      },
    },
  },
}];
